import {sectionWeightModes,sectionWeightFields,weightCubic,weightSegmentControls} from './section-weight-cubic.js';
import {curveStoredTangent,curveKeyWeight,curveControlValue} from './curve-sampling.js';
import {sequenceKeyPage,sequenceKeyLimits} from './sequence-key-storage.js';
export function sectionWeightCurveMarkup(section,offset=0,{linearOnly=false}={}){const keys=section.weightCurve;let html='<details class="section-weight-curve" open><summary>가중치 곡선</summary><label>사용<input type="checkbox" data-section-weight="'+section.id+'" '+(keys?'checked':'')+'></label>';if(!keys)return html+'</details>';
 const page=sequenceKeyPage({id:section.id,keys},null,offset),from=Math.max(0,page.start-1),to=Math.min(keys.length-1,page.end),min=keys[from].time,max=Math.max(keys[to].time,to===keys.length-1?section.duration:0,min+.001),x=t=>5+90*(t-min)/(max-min),y=v=>95-90*v;let curve='M'+x(min)+' '+y(keys[from].value);for(let i=from+1;i<=to;i++){const previous=keys[i-1];if(previous.interpolation==='step')curve+=' H'+x(keys[i].time)+' V'+y(keys[i].value);else if(weightCubic(previous.interpolation)){const c=weightSegmentControls(keys,i-1);curve+=' C'+x(c.aTime)+' '+y(c.aValue)+' '+x(c.bTime)+' '+y(c.bValue)+' '+x(keys[i].time)+' '+y(keys[i].value);}else curve+=' L'+x(keys[i].time)+' '+y(keys[i].value);}if(to===keys.length-1)curve+=' H'+x(max);
 html+='<svg preserveAspectRatio="none" viewBox="0 0 100 100" height="90" width="100%" aria-label="가중치 곡선"><path d="M5 5V95H95" fill="none" stroke="currentColor" opacity=".3"/><path data-weight-curve d="'+curve+'" fill="none" stroke="#83c5a5" stroke-width="2" vector-effect="non-scaling-stroke"/></svg><div class="sequence-key-navigation"><button data-weight-owner="'+section.id+'" data-weight-page="'+(page.start-page.size)+'" '+(page.start===0?'disabled data-weight-locked':'')+'>이전</button><span>'+(page.start+1)+'–'+page.end+' / '+page.count+'</span><button data-weight-owner="'+section.id+'" data-weight-page="'+(page.start+page.size)+'" '+(page.end===page.count?'disabled data-weight-locked':'')+'>다음</button><label>키 번호<input type="number" min="1" max="'+page.count+'" data-weight-owner="'+section.id+'" data-weight-jump value="'+(page.start+1)+'"></label></div><small>'+Number(min.toPrecision(6))+'–'+Number(max.toPrecision(6))+'초</small>';
 html+='<div class="section-weight-actions"><button data-weight-owner="'+section.id+'" data-weight-add '+(keys.length>=sequenceKeyLimits.perTrack?'disabled data-weight-locked':'')+'>키 추가</button>';for(const [action,label]of[['increase','증가'],['decrease','감소'],['pulse','봉우리']])html+='<button data-weight-owner="'+section.id+'" data-weight-preset="'+action+'">'+label+'</button>';html+='</div>';const attr=(index,field)=>'data-weight-owner="'+section.id+'" data-weight-index="'+index+'" data-weight-field="'+field+'"';const modes=linearOnly?['linear','step']:null,labels={linear:'선형',step:'계단',auto:'자동 곡선',clampedAuto:'클램프 자동',user:'수동 탄젠트',break:'분리 탄젠트'},controls=(i,k)=>{if(linearOnly||!weightCubic(k.interpolation)&&!weightCubic(keys[i-1]?.interpolation))return '';const labels={arriveTangent:'이전 기울기',leaveTangent:'다음 기울기',arriveWeight:'이전 시간 핸들',leaveWeight:'다음 시간 핸들',arriveControl:'이전 값 핸들',leaveControl:'다음 값 핸들'};return '<details><summary>곡선 핸들</summary>'+sectionWeightFields.map(field=>{const value=field.endsWith('Tangent')?curveStoredTangent(keys,i,0,field,'linear'):field.endsWith('Weight')?curveKeyWeight(k,0,field):curveControlValue(keys,i,0,field.startsWith('arrive')?'arrive':'leave','linear');return '<label>'+labels[field]+'<input type="number" step=".01" '+attr(i,field)+' value="'+value+'" '+(k.interpolation==='clampedAuto'?'disabled data-weight-locked':'')+'></label>';}).join('')+'</details>';};for(const [i,k]of page.entries)html+='<div class="section-weight-key"><label>구간 시간<input type="number" step=".01" '+attr(i,'time')+' value="'+k.time+'" '+(!i?'disabled data-weight-locked':'')+'></label><label>가중치<input type="number" min="0" max="1" step=".01" '+attr(i,'value')+' value="'+k.value+'"></label><select aria-label="다음 구간 보간" '+attr(i,'interpolation')+(linearOnly?'':' data-weight-modes')+'>'+(modes||[k.interpolation||'linear']).map(mode=>'<option value="'+mode+'" '+((k.interpolation||'linear')===mode?'selected':'')+'>'+labels[mode]+'</option>').join('')+'</select>'+controls(i,k)+'<button data-weight-owner="'+section.id+'" data-weight-remove="'+i+'" '+(!i?'disabled data-weight-locked':'')+' aria-label="가중치 키 삭제">×</button></div>';
 return html+'</details>';
}

const weightModeLabels={linear:'선형',step:'계단',auto:'자동 곡선',clampedAuto:'클램프 자동',user:'수동 탄젠트',break:'분리 탄젠트'};
export function populateWeightCurveModes(select){if(!select?.hasAttribute?.('data-weight-modes'))return false;const value=select.value;if(!sectionWeightModes.includes(value))return false;select.innerHTML=sectionWeightModes.map(mode=>'<option value="'+mode+'">'+weightModeLabels[mode]+'</option>').join('');select.value=value;select.removeAttribute('data-weight-modes');return true;}
